/// The `SYSP` operation `op1:CRn:CRm:op2`, if it has a name.
pub fn sysp(op1: u32, crn: u32, crm: u32, op2: u32) -> Option<Operation> {
    let key = (op1 << 11) | (crn << 7) | (crm << 3) | op2;
    let index = SYSP
        .binary_search_by(|(other, _)| u32::from(*other).cmp(&key))
        .ok()?;
    SYSP.get(index).map(|(_, operation)| *operation)
}
